def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.column_stack([np.ones(n)] + [np.array([s == l for s in feats.stratum], float) for l in labs[1:]])
    def ll(cols):
        Z = np.column_stack([S] + cols) if cols else S
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            mu = 1 / (1 + np.exp(-np.clip(Z @ b, -30, 30)))
            w = mu * (1 - mu) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            d = np.linalg.solve(H, Z.T @ (y - mu)); b += d
            if np.max(np.abs(d)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))
    R = np.corrcoef(X.T); R = np.nan_to_num(R)
    def pv(g, df=1): return stats.chi2.sf(max(2 * g, 0), df)
    sel = []; base = ll([])
    gates = [0.05 / p, 0.05 / p]
    while len(sel) < MAX_DRIVERS:
        cur = ll([X[:, j] for j in sel]); best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            g = ll([X[:, k] for k in sel] + [X[:, j]]) - cur
            if best is None or g > best[0]: best = (g, j)
        if best is None or pv(best[0]) > gates[min(len(sel), 1)]: break
        j = best[1]; others = [k for k in sel]
        cl = [c for c in range(p) if abs(R[j, c]) >= 0.6 and c not in sel and not any(abs(R[c, k]) >= 0.6 for k in sel)]
        if len(cl) > 1:
            lls = {c: ll([X[:, k] for k in others] + [X[:, c]]) for c in cl}
            ok = [c for c in cl if lls[c] >= lls[j] - (3 if len(cl) > 2 else 2)]
            def resid(c):
                b0 = lls[c]
                return sum(ll([X[:, k] for k in others] + [X[:, c], X[:, m]]) - b0 for m in cl if m != c)
            j = max(ok, key=lambda c: np.abs(R[c, cl]).sum()) if len(cl) > 2 else min(ok, key=resid)
        sel.append(j)
    changed = True
    while changed and sel:
        changed = False
        full = ll([X[:, k] for k in sel])
        for j in list(sel):
            g = full - ll([X[:, k] for k in sel if k != j])
            if pv(g) > 0.05 / p:
                sel.remove(j); changed = True; break
    # products: score prescreen over all pairs+squares, then 1-df LR given mains
    prods = []
    Zc = [X[:, k] for k in sel]
    Z0 = np.column_stack([S] + Zc) if Zc else S
    from sklearn.linear_model import LogisticRegression
    m = LogisticRegression(C=1e6, max_iter=500).fit(Z0[:, 1:], y) if Z0.shape[1] > 1 else None
    mu = m.predict_proba(Z0[:, 1:])[:, 1] if m is not None else np.full(n, y.mean())
    r = y - mu; w = mu * (1 - mu)
    pairs = [(a, c) for a in range(p) for c in range(a, p)]
    P = np.einsum('ni,nj->nij', X, X)
    sc = (np.einsum('n,nij->ij', r, P) ** 2) / (np.einsum('n,nij->ij', w, P ** 2) + 1e-9)
    cand = sorted(pairs, key=lambda t: -sc[t])[:15]
    alpha = 0.005 / (p * (p + 1) / 2)
    for a, c in cand:
        if len(prods) >= 2 or any({a, c} & set(q) for q in prods): continue
        mains = list(dict.fromkeys(sel + [a, c]))
        base_c = [X[:, k] for k in mains] + [X[:, q[0]] * X[:, q[1]] for q in prods]
        g = ll(base_c + [X[:, a] * X[:, c]]) - ll(base_c)
        if pv(g) < alpha: prods.append((a, c))
    for a, c in prods:
        for k in (a, c):
            if k not in sel: sel.append(k)
    drivers = tuple(ids[j] for j in sel[:MAX_DRIVERS])
    return Design(drivers=drivers, columns=tuple(ids[j] for j in sel),
                  products=tuple((ids[a], ids[c]) for a, c in prods), loadings={})

